import React from "react";
import anime from "animejs";
import { useEffect } from "react";

// Constants for grid dimensions
const GRID_WIDTH = 20;
const GRID_HEIGHT = 17;

// Main AnimatedDots Component
const AnimatedDots = () => {
  return (
    <div className="dots-background">
      <DotGrid />
    </div>
  );
};

// DotGrid Component
const DotGrid = () => {
  // Handle Click Animation
  const handleDotClick = (e: any) => {
    anime({
      targets: ".dot-point",
      scale: [
        { value: 1.35, easing: "easeOutSine", duration: 250 },
        { value: 1, easing: "easeInOutQuad", duration: 500 },
      ],
      translateY: [
        { value: -15, easing: "easeOutSine", duration: 250 },
        { value: 0, easing: "easeInOutQuad", duration: 500 },
      ],
      opacity: [
        { value: 1, easing: "easeOutSine", duration: 250 },
        { value: 0.5, easing: "easeInOutQuad", duration: 500 },
      ],
      delay: anime.stagger(100, {
        grid: [GRID_WIDTH, GRID_HEIGHT],
        from: e.target.dataset.index,
      }),
    });
  };

  useEffect(() => {
    const interval = setInterval(() => {
      const randomIndex = Math.floor(Math.random() * (GRID_WIDTH * GRID_HEIGHT));
      const fakeEvent = { target: { dataset: { index: randomIndex } } }; // Simulate a click event
      handleDotClick(fakeEvent);
    }, 5000); // Every 5 seconds
  
    return () => clearInterval(interval); // Cleanup on unmount
  }, []);
  

  // Generate Grid of Dots
  const dots = [];
  let index = 0;
  for (let i = 0; i < GRID_WIDTH; i++) {
    for (let j = 0; j < GRID_HEIGHT; j++) {
      dots.push(
        <div
          className="group cursor-crosshair rounded-full p-2 transition-colors hover:bg-slate-600"
          data-index={index}
          key={`${i}-${j}`}
        >
          <div
            className="dot-point h-2 w-2 rounded-full bg-gradient-to-b from-slate-700 to-slate-400 opacity-50 group-hover:from-indigo-600 group-hover:to-white"
            data-index={index}
          />
        </div>
      );
      index++;
    }
  }

  return (
    <div
      onClick={handleDotClick}
      style={{ gridTemplateColumns: `repeat(${GRID_WIDTH}, 1fr)` }}
      className="grid w-full h-full"
    >
      {dots}
    </div>
  );
};

export default AnimatedDots;